<template>
  <button class="toy-scene" :class="{boop:poked,quiet:!active}" aria-label="戳戳 GenSticker Logo" @click="poke" @animationend="settle">
    <view class="toy-orbit orbit-one"/><view class="toy-orbit orbit-two"/>
