<script>
import {ref,onUnmounted} from 'vue'
export default {props:{active:{type:Boolean,default:true},showHint:{type:Boolean,default:true}},setup(){const poked=ref(false);let timer;onUnmounted(()=>clearTimeout(timer));return{poked,poke:()=>{if(poked.value)return;clearTimeout(timer);poked.value=true;timer=setTimeout(()=>{poked.value=false},700)},settle:()=>{poked.value=false}}}}
</script>
